import { Given, When, Then, And } from "@cucumber/cucumber";
import SauceDemoLoginSmokePage from "../../src/pages/SauceDemoLoginSmokePage.js";

function getPageObject(world) {
  if (!world.generatedPage) {
    world.generatedPage = new SauceDemoLoginSmokePage(world.page);
  }
  return world.generatedPage;
}

Given("the user launches the application", async function() {
  const pageObject = getPageObject(this);
  await pageObject.launchApplication();
});

When("the user logs in using test data row {string}", async function(rowName) {
  const pageObject = getPageObject(this);
  const row = await this.excelHelper.readRow("src/data/TestData.xlsx", "LoginData", rowName);
  await pageObject.loginWithCredentials(row.username, row.password);
});

Then("the user should be navigated to the inventory page", async function() {
  const pageObject = getPageObject(this);
  await pageObject.assertInventoryPageVisible();
});

import { AppConfig } from "../config/AppConfig.js";
import BasePage from "./BasePage.js";

export class SauceDemoLoginSmokePage extends BasePage {
  constructor(page) {
    super(page);
    this.locatorDefinitions = [
      { name: "usernameInput", selector: "[data-test='username']", description: "Username Input" },
      { name: "passwordInput", selector: "[data-test='password']", description: "Password Input" },
      { name: "loginButton", selector: "[data-test='login-button']", description: "Login Button" },
      { name: "inventoryContainer", selector: "[data-test='inventory-container']", description: "Inventory Container" }
    ];
  }

  locator(key) {
    return this.locatorByKey(this.locatorDefinitions, key);
  }

  async launchApplication() {
    await this.uiUtils.navigateToWithLog(AppConfig.baseUrl, { context: { page: this.page } });
  }

  async loginWithCredentials(username, password) {
    await this.uiUtils.clearAndTypeWithLog(this.locator("usernameInput"), username, "Username Input", { context: { page: this.page } });
    await this.uiUtils.clearAndTypeWithLog(this.locator("passwordInput"), password, "Password Input", { context: { page: this.page } });
    await this.uiUtils.clickWithLog(this.locator("loginButton"), "Login Button", { context: { page: this.page } });
  }

  async assertInventoryPageVisible() {
    await this.assertionUtils.expectElementVisibleWithLog(this.locator("inventoryContainer"), "Inventory Container", { context: { page: this.page } });
  }
}

export default SauceDemoLoginSmokePage;
